20	import ZRText from 'zrender/src/graphic/Text';
21	import { LabelExtendedTextStyle, LabelLayoutOption, LabelMarginType, NullUndefined } from '../util/types';
22	import {
23	    BoundingRect, OrientedBoundingRect, Polyline, expandOrShrinkRect,
24	    isBoundingRectAxisAligned
25	} from '../util/graphic';
26	import type Element from 'zrender/src/Element';
27	import { PointLike } from 'zrender/src/core/Point';
28	import { each, extend, retrieve2 } from 'zrender/src/core/util';
29	import { normalizeCssArray } from '../util/format';
30	import { BoundingRectIntersectOpt } from 'zrender/src/core/BoundingRect';
31	import { MatrixArray } from 'zrender/src/core/matrix';
32	
33	// Also prevent duck typing.
34	export const LABEL_LAYOUT_INFO_KIND_RAW = 1 as const;
35	export const LABEL_LAYOUT_INFO_KIND_COMPUTED = 2 as const;
36	
37	// PENDING: a LabelLayoutInfoRaw with `defaultAttr.ignore: false` will become a NullUndefined,
38	//  rather than a LabelLayoutInfoComputed.
39	export type LabelLayoutInfoAll = LabelLayoutInfoRaw | LabelLayoutInfoComputed | NullUndefined;
40	
41	interface LabelLayoutInfoBase {
42	    label: ZRText
43	    labelLine?: Polyline | NullUndefined
44	    layoutOption?: LabelLayoutOption | NullUndefined
45	    priority: number
46	    // Save the original value that may be modified in overlap resolving.
47	    defaultAttr: {
48	        ignore?: boolean
49	        labelGuideIgnore?: boolean
50	    }
51	    ignoreMargin?: boolean; // For backward compatibility.
52	
53	    // In grid (cartesian) estimation process (for `grid.containLabel` and related overflow resolving handlings),
54	    // the `gridRect` is shrunk gradually according to the last union boundingRect of the axis labels and names.
55	    // But the `ignore` stretegy (such as in `hideOverlap` and `fixMinMaxLabelShow`) affects this process
56	    // significantly - the outermost labels might be determined `ignore:true` in a big `gridRect`, but be determined
57	    // `ignore:false` in a shrunk `gridRect`. (e.g., if the third label touches the outermost label in a shrunk
58	    // `gridRect`.) That probably causes the result overflowing unexpectedly. Therefore, `suggestIgnore` is
59	    // introduced to ensure the `ignore` consistent during that estimation process.
60	    suggestIgnore?: boolean;
61	}
62	
63	export interface LabelLayoutInfoRaw extends LabelLayoutInfoBase {
64	    kind: typeof LABEL_LAYOUT_INFO_KIND_RAW
65	    // Should no other properties - ensure to be a subset of LabelLayoutInfoComputed.
66	}
67	
68	export interface LabelLayoutInfoComputed extends LabelLayoutInfoBase, LabelIntersectionCheckInfo {
69	    kind: typeof LABEL_LAYOUT_INFO_KIND_COMPUTED
70	    // The original props in `LabelLayoutInfoBase` are preserved.
71	
72	    // ------ Computed properites ------
73	    // All of the members in `LabelIntersectionCheckInfo`.
74	}
75	
76	export interface LabelIntersectionCheckInfo {
77	    // Global rect from `localRect`
78	    rect: BoundingRect
79	    // Weither the localRect aligns to screen-pixel x or y axis.
80	    axisAligned: boolean
81	    // Considering performance, obb is not created until it is really needed.
82	    // Use `ensureOBB(labelLayoutInfo)` to create and cache obb before using it,
83	    // created by `localRect`&`transform`.
84	    obb: OrientedBoundingRect | NullUndefined
85	    // localRect of the label.
86	    // [CAUTION] do not modify it, since it may be the internal data structure of the el.
87	    localRect: BoundingRect
88	    // transform of `label`. If `label` has no `transform`, this prop is `NullUndefined`.
89	    // [CAUTION] do not modify it, since it may be the internal data structure of the el.
90	    transform: number[] | NullUndefined
91	}
92	
93	export function createLabelLayoutList(
94	    rawList: LabelLayoutInfoRaw[]
95	): LabelLayoutInfoComputed[] {
96	    const resultList: LabelLayoutInfoComputed[] = [];
97	    each(rawList, raw => {
98	        // PENDING: necessary?
99	        raw = extend({}, raw);
100	        const layoutInfo = prepareLabelLayoutInfo(raw);
101	        if (layoutInfo) {
102	            resultList.push(layoutInfo);
103	        }
104	    });
105	    return resultList;
106	}
107	
108	/**
109	 * If `defaultAttr.ignore: true`, return `NullUndefined`.
110	 *  (the caller is reponsible for ensuring the label is always `ignore: true`.)
111	 * Otherwise the `layoutInfo` will be modified and returned.
112	 * `label.ignore` is not necessarily falsy, since it might be modified by some overlap resolving handling.
113	 *
114	 * The result can also be the input of this method.
115	 *
116	 * @see ensureLabelLayoutInfoComputed
117	 */
118	function prepareLabelLayoutInfo(
119	    layoutInfo: LabelLayoutInfoAll
120	): LabelLayoutInfoComputed | NullUndefined {
121	
122	    if (!layoutInfo || layoutInfo.defaultAttr.ignore) {
123	        return;
124	    }
125	
126	    const label = layoutInfo.label;
127	    const ignoreMargin = layoutInfo.ignoreMargin;
128	
129	    const transform = label.getComputedTransform();
130	    // NOTE: Get bounding rect after getComputedTransform, or label may not been updated by the host el.
131	    let localRect = label.getBoundingRect();
132	    const axisAligned = isBoundingRectAxisAligned(transform);
133	
134	    if (!ignoreMargin) {
135	        localRect = applyTextMarginToLocalRect(label, localRect);
136	    }
137	
138	    const globalRect = localRect.clone();
139	    globalRect.applyTransform(transform);
140	
141	    if (!ignoreMargin && (label.style as LabelExtendedTextStyle).__marginType === LabelMarginType.minMargin) {
142	        // `minMargin` only support number value.
143	        const halfMinMargin = ((label.style.margin as number) || 0) / 2;
144	        expandOrShrinkRect(globalRect, halfMinMargin, false, false);
145	    }
146	
147	    const computed = layoutInfo as LabelLayoutInfoComputed;
148	    computed.kind = LABEL_LAYOUT_INFO_KIND_COMPUTED,
149	    // --- computed properties ---
150	    computed.rect = globalRect;
151	    computed.localRect = localRect;
152	    computed.obb = null, // will be created by `ensureOBB` when using.
153	    computed.axisAligned = axisAligned;
154	    computed.transform = transform;
155	
156	    return computed;
157	}
158	
159	/**
160	 * The reverse operation of `ensureLabelLayoutInfoComputedv`.
161	 */
162	export function rollbackToLabelLayoutInfoRaw(
163	    labelLayoutInfo: LabelLayoutInfoAll
164	): LabelLayoutInfoRaw {
165	    if (labelLayoutInfo == null) {
166	        return;
167	    }
168	    const raw = labelLayoutInfo as unknown as LabelLayoutInfoRaw;
169	    raw.kind = LABEL_LAYOUT_INFO_KIND_RAW;
170	    return raw;
171	}
172	
173	/**
174	 * This method supports that the label layout info is not computed until needed,
175	 * for performance consideration.
176	 *
177	 * [CAUTION]
178	 *  - If the raw label is changed, must call
179	 *    `ensureLabelLayoutInfoComputed(rollbackToLabelLayoutInfoRaw(layoutInfo))`
180	 *    to recreate the layout info.
181	 *  - Null checking is needed for the result. @see prepareLabelLayoutInfo
182	 *
183	 * Usage:
184	 *  To make a copy of labelLayoutInfo, simply:
185	 *      const layoutInfoCopy = rollbackToLabelLayoutInfoRaw(extends({}, someLabelLayoutInfo));
186	 */
187	export function ensureLabelLayoutInfoComputed(
188	    labelLayoutInfo: LabelLayoutInfoAll
189	): LabelLayoutInfoComputed | NullUndefined {
190	    if (!labelLayoutInfo) {
191	        return;
192	    }
193	    if (labelLayoutInfo.kind !== LABEL_LAYOUT_INFO_KIND_COMPUTED) {
194	        labelLayoutInfo = prepareLabelLayoutInfo(labelLayoutInfo);
195	    }
196	    return labelLayoutInfo;
197	}
198	
199	export function prepareIntersectionCheckInfo(
200	    localRect: BoundingRect, transform: MatrixArray | NullUndefined
201	): LabelIntersectionCheckInfo {
202	    const globalRect = localRect.clone();
203	    globalRect.applyTransform(transform);
204	    return {
205	        obb: null,
206	        rect: globalRect,
207	        localRect,
208	        axisAligned: isBoundingRectAxisAligned(transform),
209	        transform,
210	    };
211	}
212	
213	export function createSingleLayoutInfoComputed(el: ZRText): LabelLayoutInfoComputed | NullUndefined {
214	    return ensureLabelLayoutInfoComputed({
215	        kind: LABEL_LAYOUT_INFO_KIND_RAW,
216	        label: el,
217	        priority: el.z2,
218	        defaultAttr: {ignore: el.ignore},
219	    });
220	}
221	
222	/**
223	 * Create obb if no one, can cache it.
224	 */
225	function ensureOBB(layoutInfo: LabelIntersectionCheckInfo): OrientedBoundingRect {
226	    return layoutInfo.obb || (
227	        layoutInfo.obb = new OrientedBoundingRect(layoutInfo.localRect, layoutInfo.transform)
228	    );
229	}
230	
231	/**
232	 * The input localRect is never modified.
233	 * The returned localRect maybe the input localRect.
234	 */
235	export function applyTextMarginToLocalRect(
236	    label: ZRText,
237	    localRect: BoundingRect,
238	): BoundingRect {
239	    if ((label.style as LabelExtendedTextStyle).__marginType !== LabelMarginType.textMargin) {
240	        return localRect;
241	    }
242	    const textMargin = normalizeCssArray(retrieve2(label.style.margin, [0, 0]));
243	    localRect = localRect.clone();
244	    expandOrShrinkRect(localRect, textMargin, false, false);
245	    return localRect;
246	}
247	
248	function shiftLayout(
249	    list: Pick<LabelLayoutInfoComputed, 'rect' | 'label'>[],
250	    xyDim: 'x' | 'y',
251	    sizeDim: 'width' | 'height',
252	    minBound: number,
253	    maxBound: number,
254	    balanceShift: boolean
255	) {
256	    const len = list.length;
257	
258	    if (len < 2) {
259	        return;
260	    }
261	
262	    list.sort(function (a, b) {
263	        return a.rect[xyDim] - b.rect[xyDim];
264	    });
265	
266	    let lastPos = 0;
267	    let delta;
268	    let adjusted = false;
269	
270	    const shifts = [];
271	    let totalShifts = 0;
272	    for (let i = 0; i < len; i++) {
273	        const item = list[i];
274	        const rect = item.rect;
275	        delta = rect[xyDim] - lastPos;
276	        if (delta < 0) {
277	            // shiftForward(i, len, -delta);
278	            rect[xyDim] -= delta;
279	            item.label[xyDim] -= delta;
280	            adjusted = true;
281	        }
282	        const shift = Math.max(-delta, 0);
283	        shifts.push(shift);
284	        totalShifts += shift;
285	
286	        lastPos = rect[xyDim] + rect[sizeDim];
287	    }
288	    if (totalShifts > 0 && balanceShift) {
289	        // Shift back to make the distribution more equally.
290	        shiftList(-totalShifts / len, 0, len);
291	    }
292	
293	    // TODO bleedMargin?
294	    const first = list[0];
295	    const last = list[len - 1];
296	    let minGap: number;
297	    let maxGap: number;
298	    updateMinMaxGap();
299	
300	    // If ends exceed two bounds, squeeze at most 80%, then take the gap of two bounds.
301	    minGap < 0 && squeezeGaps(-minGap, 0.8);
302	    maxGap < 0 && squeezeGaps(maxGap, 0.8);
303	    updateMinMaxGap();
304	    takeBoundsGap(minGap, maxGap, 1);
305	    takeBoundsGap(maxGap, minGap, -1);
306	
307	    // Handle bailout when there is not enough space.
308	    updateMinMaxGap();
309	
310	    if (minGap < 0) {
311	        squeezeWhenBailout(-minGap);
312	    }
313	    if (maxGap < 0) {
314	        squeezeWhenBailout(maxGap);
315	    }
316	
317	    function updateMinMaxGap() {
318	        minGap = first.rect[xyDim] - minBound;
319	        maxGap = maxBound - last.rect[xyDim] - last.rect[sizeDim];
320	    }
321	
322	    function takeBoundsGap(gapThisBound: number, gapOtherBound: number, moveDir: 1 | -1) {
323	        if (gapThisBound < 0) {
324	            // Move from other gap if can.
325	            const moveFromMaxGap = Math.min(gapOtherBound, -gapThisBound);
326	            if (moveFromMaxGap > 0) {
327	                shiftList(moveFromMaxGap * moveDir, 0, len);
328	                const remained = moveFromMaxGap + gapThisBound;
329	                if (remained < 0) {
330	                    squeezeGaps(-remained * moveDir, 1);
331	                }
332	            }
333	            else {
334	                squeezeGaps(-gapThisBound * moveDir, 1);
335	            }
336	        }
337	    }
338	
339	    function shiftList(delta: number, start: number, end: number) {
340	        if (delta !== 0) {
341	            adjusted = true;
342	        }
343	        for (let i = start; i < end; i++) {
344	            const item = list[i];
345	            const rect = item.rect;
346	            rect[xyDim] += delta;
347	            item.label[xyDim] += delta;
348	        }
349	    }
350	
351	    // Squeeze gaps if the labels exceed margin.
352	    function squeezeGaps(delta: number, maxSqeezePercent: number) {
353	        const gaps: number[] = [];
354	        let totalGaps = 0;
355	        for (let i = 1; i < len; i++) {
356	            const prevItemRect = list[i - 1].rect;
357	            const gap = Math.max(list[i].rect[xyDim] - prevItemRect[xyDim] - prevItemRect[sizeDim], 0);
358	            gaps.push(gap);
359	            totalGaps += gap;
360	        }
361	        if (!totalGaps) {
362	            return;
363	        }
364	
365	        const squeezePercent = Math.min(Math.abs(delta) / totalGaps, maxSqeezePercent);
366	
367	        if (delta > 0) {
368	            for (let i = 0; i < len - 1; i++) {
369	                // Distribute the shift delta to all gaps.
370	                const movement = gaps[i] * squeezePercent;
371	                // Forward
372	                shiftList(movement, 0, i + 1);
373	            }
374	        }
375	        else {
376	            // Backward
377	            for (let i = len - 1; i > 0; i--) {
378	                // Distribute the shift delta to all gaps.
379	                const movement = gaps[i - 1] * squeezePercent;
380	                shiftList(-movement, i, len);
381	            }
382	        }
383	    }
384	
385	    /**
386	     * Squeeze to allow overlap if there is no more space available.
387	     * Let other overlapping strategy like hideOverlap do the job instead of keep exceeding the bounds.
388	     */
389	    function squeezeWhenBailout(delta: number) {
390	        const dir = delta < 0 ? -1 : 1;
391	        delta = Math.abs(delta);
392	        const moveForEachLabel = Math.ceil(delta / (len - 1));
393	
394	        for (let i = 0; i < len - 1; i++) {
395	            if (dir > 0) {
396	                // Forward
397	                shiftList(moveForEachLabel, 0, i + 1);
398	            }
399	            else {
400	                // Backward
401	                shiftList(-moveForEachLabel, len - i - 1, len);
402	            }
403	
404	            delta -= moveForEachLabel;
405	
406	            if (delta <= 0) {
407	                return;
408	            }
409	        }
410	    }
411	
412	    return adjusted;
413	}
414	
415	/**
416	 * Adjust labels on x direction to avoid overlap.
417	 */
418	export function shiftLayoutOnX(
419	    list: Pick<LabelLayoutInfoComputed, 'rect' | 'label'>[],
420	    leftBound: number,
421	    rightBound: number,
422	    // If average the shifts on all labels and add them to 0
423	    // TODO: Not sure if should enable it.
424	    // Pros: The angle of lines will distribute more equally
425	    // Cons: In some layout. It may not what user wanted. like in pie. the label of last sector is usually changed unexpectedly.
426	    balanceShift?: boolean
427	): boolean {
428	    return shiftLayout(list, 'x', 'width', leftBound, rightBound, balanceShift);
429	}
430	
431	/**
432	 * Adjust labels on y direction to avoid overlap.
433	 */
434	export function shiftLayoutOnY(
435	    list: Pick<LabelLayoutInfoComputed, 'rect' | 'label'>[],
436	    topBound: number,
437	    bottomBound: number,
438	    // If average the shifts on all labels and add them to 0
439	    balanceShift?: boolean
440	): boolean {
441	    return shiftLayout(list, 'y', 'height', topBound, bottomBound, balanceShift);
442	}
443	
444	/**
445	 * [CAUTION]: the `label.ignore` in the input is not necessarily falsy.
446	 *  this method checks intersection regardless of current `ignore`,
447	 *  if no intersection, restore the `ignore` to `defaultAttr.ignore`.
448	 *  And `labelList` will be modified.
449	 *  Therefore, if some other overlap resolving strategy has ignored some elements,
450	 *  do not input them to this method.
451	 * PENDING: review the diff between the requirements from LabelManager and AxisBuilder,
452	 *  and uniform the behavior?
453	 */
454	export function hideOverlap(labelList: LabelLayoutInfoAll[]): void {
455	    const displayedLabels: LabelLayoutInfoComputed[] = [];
456	
457	    // TODO, render overflow visible first, put in the displayedLabels.
458	    labelList.sort(function (a, b) {
459	        return ((b.suggestIgnore ? 1 : 0) - (a.suggestIgnore ? 1 : 0))
460	            || (b.priority - a.priority);
461	    });
462	
463	    function hideEl(el: Element) {
464	        if (!el.ignore) {
465	            // Show on emphasis.
466	            const emphasisState = el.ensureState('emphasis');
467	            if (emphasisState.ignore == null) {
468	                emphasisState.ignore = false;
469	            }
470	        }
471	
472	        el.ignore = true;
473	    }
474	
475	    for (let i = 0; i < labelList.length; i++) {
476	        const labelItem = ensureLabelLayoutInfoComputed(labelList[i]);
477	
478	        if (!labelItem || labelItem.label.ignore) {
479	            continue;
480	        }
481	
482	        const label = labelItem.label;
483	        const labelLine = labelItem.labelLine;
484	
485	        // NOTICE: even when the with/height of globalRect of a label is 0, the label line should
486	        // still be displayed, since we should follow the concept of "truncation", meaning that
487	        // something exists even if it cannot be fully displayed. A visible label line is necessary
488	        // to allow users to get a tooltip with label info on hover.
489	
490	        let overlapped = false;
491	        for (let j = 0; j < displayedLabels.length; j++) {
492	            if (labelIntersect(labelItem, displayedLabels[j], null, {touchThreshold: 0.05})) {
493	                overlapped = true;
494	                break;
495	            }
496	        }
497	
498	        // TODO Callback to determine if this overlap should be handled?
499	        if (overlapped) {
500	            hideEl(label);
501	            labelLine && hideEl(labelLine);
502	        }
503	        else {
504	            label.attr('ignore', labelItem.defaultAttr.ignore);
505	            labelLine && labelLine.attr('ignore', labelItem.defaultAttr.labelGuideIgnore);
506	
507	            displayedLabels.push(labelItem);
508	        }
509	    }
510	}
511	
512	/**
513	 * [NOTICE]:
514	 *  - `label.ignore` is not considered - no requirement so far.
515	 *  - `baseLayoutInfo` and `targetLayoutInfo` may be modified - obb may be created and saved.
516	 *
517	 * Enable fast check for performance; use obb if inevitable.
518	 * If `mtv` is used, `targetLayoutInfo` can be moved based on the values filled into `mtv`.
519	 */
520	export function labelIntersect(
521	    baseLayoutInfo: LabelIntersectionCheckInfo | NullUndefined,
522	    targetLayoutInfo: LabelIntersectionCheckInfo | NullUndefined,
523	    mtv?: PointLike,
524	    intersectOpt?: BoundingRectIntersectOpt
525	): boolean {
526	    if (!baseLayoutInfo || !targetLayoutInfo) {
527	        return false;
528	    }
529	    // Fast rejection.
530	    if (!baseLayoutInfo.rect.intersect(targetLayoutInfo.rect, mtv, intersectOpt)) {
531	        return false;
532	    }
533	    if (baseLayoutInfo.axisAligned && targetLayoutInfo.axisAligned) {
534	        return true; // obb is the same as the normal bounding rect.
535	    }
536	    return ensureOBB(baseLayoutInfo).intersect(ensureOBB(targetLayoutInfo), mtv, intersectOpt);
537	}
