200	    /**
201	     * Add label to manager
202	     */
203	    private _addLabel(
204	        dataIndex: number | null | undefined,
205	        dataType: SeriesDataType | null | undefined,
206	        seriesModel: SeriesModel,
207	        label: ZRText,
208	        layoutOptionOrCb: LabelDesc['layoutOptionOrCb']
209	    ) {
210	        const labelStyle = label.style;
211	        const hostEl = label.__hostTarget;
212	        const textConfig = hostEl.textConfig || {};
213	
214	        // TODO: If label is in other state.
215	        const labelTransform = label.getComputedTransform();
216	        const labelRect = label.getBoundingRect().plain();
217	        BoundingRect.applyTransform(labelRect, labelRect, labelTransform);
218	
219	        if (labelTransform) {
220	            dummyTransformable.setLocalTransform(labelTransform);
221	        }
222	        else {
223	            // Identity transform.
224	            dummyTransformable.x = dummyTransformable.y = dummyTransformable.rotation =
225	                dummyTransformable.originX = dummyTransformable.originY = 0;
226	            dummyTransformable.scaleX = dummyTransformable.scaleY = 1;
227	        }
228	
229	        dummyTransformable.rotation = normalizeRadian(dummyTransformable.rotation);
230	
231	        const host = label.__hostTarget;
232	        let hostRect;
233	        if (host) {
234	            hostRect = host.getBoundingRect().plain();
235	            const transform = host.getComputedTransform();
236	            BoundingRect.applyTransform(hostRect, hostRect, transform);
237	        }
238	
239	        const labelGuide = hostRect && host.getTextGuideLine();
240	
241	        this._labelList.push({
242	            kind: LABEL_LAYOUT_INFO_KIND_RAW,
243	            label,
244	            labelLine: labelGuide,
245	
246	            seriesModel,
247	            dataIndex,
248	            dataType,
249	
250	            layoutOptionOrCb,
251	            layoutOption: null,
252	
253	            rect: labelRect,
254	
255	            hostRect,
256	
257	            // Label with lower priority will be hidden when overlapped
258	            // Use rect size as default priority
259	            priority: hostRect ? hostRect.width * hostRect.height : 0,
260	
261	            // Save default label attributes.
262	            // For restore if developers want get back to default value in callback.
263	            defaultAttr: {
264	                ignore: label.ignore,
265	                labelGuideIgnore: labelGuide && labelGuide.ignore,
266	
267	                x: dummyTransformable.x,
268	                y: dummyTransformable.y,
269	                scaleX: dummyTransformable.scaleX,
270	                scaleY: dummyTransformable.scaleY,
271	                rotation: dummyTransformable.rotation,
272	
273	                style: {
274	                    x: labelStyle.x,
275	                    y: labelStyle.y,
276	
277	                    align: labelStyle.align,
278	                    verticalAlign: labelStyle.verticalAlign,
279	                    width: labelStyle.width,
280	                    height: labelStyle.height,
281	
282	                    fontSize: labelStyle.fontSize
283	                },
284	
285	                cursor: label.cursor,
286	
287	                attachedPos: textConfig.position,
288	                attachedRot: textConfig.rotation
289	            }
290	        });
291	    }
292	
293	    addLabelsOfSeries(chartView: ChartView) {
294	        this._chartViewList.push(chartView);
295	
296	        const seriesModel = chartView.__model;
297	
298	        const layoutOption = seriesModel.get('labelLayout');
299	
300	        /**
301	         * Ignore layouting if it's not specified anything.
302	         */
303	        if (!(isFunction(layoutOption) || keys(layoutOption).length)) {
304	            return;
305	        }
306	
307	        chartView.group.traverse((child) => {
308	            if (child.ignore) {
309	                return true;    // Stop traverse descendants.
310	            }
311	
312	            // Only support label being hosted on graphic elements.
313	            const textEl = child.getTextContent();
314	            const ecData = getECData(child);
315	            // Can only attach the text on the element with dataIndex
316	            if (textEl && !(textEl as ECElement).disableLabelLayout) {
317	                this._addLabel(ecData.dataIndex, ecData.dataType, seriesModel, textEl, layoutOption);
318	            }
319	        });
320	    }
