322	    updateLayoutConfig(api: ExtensionAPI) {
323	        const width = api.getWidth();
324	        const height = api.getHeight();
325	
326	        function createDragHandler(el: Element, labelLineModel: Model) {
327	            return function () {
328	                updateLabelLinePoints(el, labelLineModel);
329	            };
330	        }
331	        for (let i = 0; i < this._labelList.length; i++) {
332	            const labelItem = this._labelList[i];
333	            const label = labelItem.label;
334	            const hostEl = label.__hostTarget;
335	            const defaultLabelAttr = labelItem.defaultAttr;
336	            let layoutOption;
337	            // TODO A global layout option?
338	            if (isFunction(labelItem.layoutOptionOrCb)) {
339	                layoutOption = labelItem.layoutOptionOrCb(
340	                    prepareLayoutCallbackParams(labelItem, hostEl)
341	                );
342	            }
343	            else {
344	                layoutOption = labelItem.layoutOptionOrCb;
345	            }
346	
347	            layoutOption = layoutOption || {};
348	            labelItem.layoutOption = layoutOption;
349	
350	            const degreeToRadian = Math.PI / 180;
351	            // TODO hostEl should always exists.
352	            // Or label should not have parent because the x, y is all in global space.
353	            if (hostEl) {
354	                hostEl.setTextConfig({
355	                    // Force to set local false.
356	                    local: false,
357	                    // Ignore position and rotation config on the host el if x or y is changed.
358	                    position: (layoutOption.x != null || layoutOption.y != null)
359	                        ? null : defaultLabelAttr.attachedPos,
360	                    // Ignore rotation config on the host el if rotation is changed.
361	                    rotation: layoutOption.rotate != null
362	                        ? layoutOption.rotate * degreeToRadian : defaultLabelAttr.attachedRot,
363	                    offset: [layoutOption.dx || 0, layoutOption.dy || 0]
364	                });
365	            }
366	            let needsUpdateLabelLine = false;
367	            if (layoutOption.x != null) {
368	                // TODO width of chart view.
369	                label.x = parsePercent(layoutOption.x, width);
370	                label.setStyle('x', 0);  // Ignore movement in style. TODO: origin.
371	                needsUpdateLabelLine = true;
372	            }
373	            else {
374	                label.x = defaultLabelAttr.x;
375	                label.setStyle('x', defaultLabelAttr.style.x);
376	            }
377	
378	            if (layoutOption.y != null) {
379	                // TODO height of chart view.
380	                label.y = parsePercent(layoutOption.y, height);
381	                label.setStyle('y', 0);  // Ignore movement in style.
382	                needsUpdateLabelLine = true;
383	            }
384	            else {
385	                label.y = defaultLabelAttr.y;
386	                label.setStyle('y', defaultLabelAttr.style.y);
387	            }
388	
389	            if (layoutOption.labelLinePoints) {
390	                const guideLine = hostEl.getTextGuideLine();
391	                if (guideLine) {
392	                    guideLine.setShape({ points: layoutOption.labelLinePoints });
393	                    // Not update
394	                    needsUpdateLabelLine = false;
395	                }
396	            }
397	
398	            const labelLayoutStore = labelLayoutInnerStore(label);
399	            labelLayoutStore.needsUpdateLabelLine = needsUpdateLabelLine;
400	
401	            label.rotation = layoutOption.rotate != null
402	                ? layoutOption.rotate * degreeToRadian : defaultLabelAttr.rotation;
403	
404	            label.scaleX = defaultLabelAttr.scaleX;
405	            label.scaleY = defaultLabelAttr.scaleY;
406	
407	            for (let k = 0; k < LABEL_OPTION_TO_STYLE_KEYS.length; k++) {
408	                const key = LABEL_OPTION_TO_STYLE_KEYS[k];
409	                label.setStyle(key, layoutOption[key] != null ? layoutOption[key] : defaultLabelAttr.style[key]);
410	            }
411	
412	
413	            if (layoutOption.draggable) {
414	                label.draggable = true;
415	                label.cursor = 'move';
416	                if (hostEl) {
417	                    let hostModel: Model<LabelLineOptionMixin> =
418	                        labelItem.seriesModel as SeriesModel<LabelLineOptionMixin>;
419	                    if (labelItem.dataIndex != null) {
420	                        const data = labelItem.seriesModel.getData(labelItem.dataType);
421	                        hostModel = data.getItemModel<LabelLineOptionMixin>(labelItem.dataIndex);
422	                    }
423	                    label.on('drag', createDragHandler(hostEl, hostModel.getModel('labelLine')));
424	                }
425	            }
426	            else {
427	                // TODO Other drag functions?
428	                label.off('drag');
429	                label.cursor = defaultLabelAttr.cursor;
430	            }
431	        }
432	    }
433	
434	    layout(api: ExtensionAPI) {
435	        const width = api.getWidth();
436	        const height = api.getHeight();
437	
438	        const labelList = createLabelLayoutList(this._labelList);
439	        const labelsNeedsAdjustOnX = filter(labelList, function (item) {
440	            return item.layoutOption.moveOverlap === 'shiftX';
441	        });
442	        const labelsNeedsAdjustOnY = filter(labelList, function (item) {
443	            return item.layoutOption.moveOverlap === 'shiftY';
444	        });
445	
446	        shiftLayoutOnX(labelsNeedsAdjustOnX, 0, width);
447	        shiftLayoutOnY(labelsNeedsAdjustOnY, 0, height);
448	
449	        const labelsNeedsHideOverlap = filter(labelList, function (item) {
450	            return item.layoutOption.hideOverlap;
451	        });
452	
453	        hideOverlap(labelsNeedsHideOverlap);
454	    }
455	
456	    /**
457	     * Process all labels. Not only labels with layoutOption.
458	     */
459	    processLabelsOverall() {
460	        each(this._chartViewList, (chartView) => {
461	            const seriesModel = chartView.__model;
462	            const ignoreLabelLineUpdate = chartView.ignoreLabelLineUpdate;
463	            const animationEnabled = seriesModel.isAnimationEnabled();
464	
465	            chartView.group.traverse((child) => {
466	                if (child.ignore && !(child as ECElement).forceLabelAnimation) {
467	                    return true;    // Stop traverse descendants.
468	                }
469	
470	                let needsUpdateLabelLine = !ignoreLabelLineUpdate;
471	                const label = child.getTextContent();
472	                if (!needsUpdateLabelLine && label) {
473	                    needsUpdateLabelLine = labelLayoutInnerStore(label).needsUpdateLabelLine;
474	                }
475	                if (needsUpdateLabelLine) {
476	                    this._updateLabelLine(child, seriesModel);
477	                }
478	
479	                if (animationEnabled) {
480	                    this._animateLabels(child, seriesModel);
481	                }
482	            });
483	        });
484	    }
485	
486	    private _updateLabelLine(el: Element, seriesModel: SeriesModel) {
487	        // Only support label being hosted on graphic elements.
488	        const textEl = el.getTextContent();
489	        // Update label line style.
490	        const ecData = getECData(el);
491	        const dataIndex = ecData.dataIndex;
492	
493	        // Only support labelLine on the labels represent data.
494	        if (textEl && dataIndex != null) {
495	            const data = seriesModel.getData(ecData.dataType);
496	            const itemModel = data.getItemModel<LabelLineOptionMixin>(dataIndex);
497	
498	            const defaultStyle: PathStyleProps = {};
499	            const visualStyle = data.getItemVisual(dataIndex, 'style');
500	            if (visualStyle) {
501	                const visualType = data.getVisual('drawType');
502	                // Default to be same with main color
503	                defaultStyle.stroke = visualStyle[visualType];
504	            }
505	            const labelLineModel = itemModel.getModel('labelLine');
506	
507	            setLabelLineStyle(el, getLabelLineStatesModels(itemModel), defaultStyle);
508	
509	            updateLabelLinePoints(el, labelLineModel);
510	        }
511	    }
512	
513	    private _animateLabels(el: Element, seriesModel: SeriesModel) {
514	        const textEl = el.getTextContent();
515	        const guideLine = el.getTextGuideLine();
516	        // Animate
517	        if (textEl
518	            // `forceLabelAnimation` has the highest priority
519	            && ((el as ECElement).forceLabelAnimation
520	                || !textEl.ignore
521	                && !textEl.invisible
522	                && !(el as ECElement).disableLabelAnimation
523	                && !isElementRemoved(el)
524	            )
525	        ) {
526	            const layoutStore = labelLayoutInnerStore(textEl);
527	            const oldLayout = layoutStore.oldLayout;
528	            const ecData = getECData(el);
529	            const dataIndex = ecData.dataIndex;
530	            const newProps = {
531	                x: textEl.x,
532	                y: textEl.y,
533	                rotation: textEl.rotation
534	            };
535	            const data = seriesModel.getData(ecData.dataType);
536	
537	            if (!oldLayout) {
538	                textEl.attr(newProps);
539	                // Disable fade in animation if value animation is enabled.
540	                if (!labelInner(textEl).valueAnimation) {
541	                    const oldOpacity = retrieve2(textEl.style.opacity, 1);
542	                    // Fade in animation
543	                    textEl.style.opacity = 0;
544	                    initProps(textEl, {
545	                        style: { opacity: oldOpacity }
546	                    }, seriesModel, dataIndex);
547	                }
548	            }
549	            else {
550	                textEl.attr(oldLayout);
551	
552	                // Make sure the animation from is in the right status.
553	                const prevStates = el.prevStates;
554	                if (prevStates) {
555	                    if (indexOf(prevStates, 'select') >= 0) {
556	                        textEl.attr(layoutStore.oldLayoutSelect);
557	                    }
558	                    if (indexOf(prevStates, 'emphasis') >= 0) {
559	                        textEl.attr(layoutStore.oldLayoutEmphasis);
560	                    }
561	                }
562	                updateProps(textEl, newProps, seriesModel, dataIndex);
563	            }
564	            layoutStore.oldLayout = newProps;
565	
566	            if (textEl.states.select) {
567	                const layoutSelect = layoutStore.oldLayoutSelect = {};
568	                extendWithKeys(layoutSelect, newProps, LABEL_LAYOUT_PROPS);
569	                extendWithKeys(layoutSelect, textEl.states.select, LABEL_LAYOUT_PROPS);
570	            }
571	
572	            if (textEl.states.emphasis) {
573	                const layoutEmphasis = layoutStore.oldLayoutEmphasis = {};
574	                extendWithKeys(layoutEmphasis, newProps, LABEL_LAYOUT_PROPS);
575	                extendWithKeys(layoutEmphasis, textEl.states.emphasis, LABEL_LAYOUT_PROPS);
576	            }
577	
578	            animateLabelValue(textEl, dataIndex, data, seriesModel, seriesModel);
579	        }
580	
581	        if (guideLine && !guideLine.ignore && !guideLine.invisible) {
582	            const layoutStore = labelLineAnimationStore(guideLine);
583	            const oldLayout = layoutStore.oldLayout;
584	            const newLayout = { points: guideLine.shape.points };
585	            if (!oldLayout) {
586	                guideLine.setShape(newLayout);
587	                guideLine.style.strokePercent = 0;
588	                initProps(guideLine, {
589	                    style: { strokePercent: 1 }
590	                }, seriesModel);
591	            }
592	            else {
593	                guideLine.attr({ shape: oldLayout });
594	                updateProps(guideLine, {
595	                    shape: newLayout
596	                }, seriesModel);
597	            }
598	
599	            layoutStore.oldLayout = newLayout;
600	        }
601	    }
602	}
