147	function avoidOverlap(
148	    labelLayoutList: LabelLayout[],
149	    cx: number,
150	    cy: number,
151	    r: number,
152	    viewWidth: number,
153	    viewHeight: number,
154	    viewLeft: number,
155	    viewTop: number
156	) {
157	    const leftList = [];
158	    const rightList = [];
159	    let leftmostX = Number.MAX_VALUE;
160	    let rightmostX = -Number.MAX_VALUE;
161	    for (let i = 0; i < labelLayoutList.length; i++) {
162	        const label = labelLayoutList[i].label;
163	        if (isPositionCenter(labelLayoutList[i])) {
164	            continue;
165	        }
166	        if (label.x < cx) {
167	            leftmostX = Math.min(leftmostX, label.x);
168	            leftList.push(labelLayoutList[i]);
169	        }
170	        else {
171	            rightmostX = Math.max(rightmostX, label.x);
172	            rightList.push(labelLayoutList[i]);
173	        }
174	    }
175	
176	    for (let i = 0; i < labelLayoutList.length; i++) {
177	        const layout = labelLayoutList[i];
178	        if (!isPositionCenter(layout) && layout.linePoints) {
179	            if (layout.labelStyleWidth != null) {
180	                continue;
181	            }
182	
183	            const label = layout.label;
184	            const linePoints = layout.linePoints;
185	
186	            let targetTextWidth;
187	            if (layout.labelAlignTo === 'edge') {
188	                if (label.x < cx) {
189	                    targetTextWidth = linePoints[2][0] - layout.labelDistance
190	                            - viewLeft - layout.edgeDistance;
191	                }
192	                else {
193	                    targetTextWidth = viewLeft + viewWidth - layout.edgeDistance
194	                            - linePoints[2][0] - layout.labelDistance;
195	                }
196	            }
197	            else if (layout.labelAlignTo === 'labelLine') {
198	                if (label.x < cx) {
199	                    targetTextWidth = leftmostX - viewLeft - layout.bleedMargin;
200	                }
201	                else {
202	                    targetTextWidth = viewLeft + viewWidth - rightmostX - layout.bleedMargin;
203	                }
204	            }
205	            else {
206	                if (label.x < cx) {
207	                    targetTextWidth = label.x - viewLeft - layout.bleedMargin;
208	                }
209	                else {
210	                    targetTextWidth = viewLeft + viewWidth - label.x - layout.bleedMargin;
211	                }
212	            }
213	            layout.targetTextWidth = targetTextWidth;
214	
215	            constrainTextWidth(layout, targetTextWidth);
216	        }
217	    }
218	
219	    adjustSingleSide(rightList, cx, cy, r, 1, viewWidth, viewHeight, viewLeft, viewTop, rightmostX);
220	    adjustSingleSide(leftList, cx, cy, r, -1, viewWidth, viewHeight, viewLeft, viewTop, leftmostX);
221	
222	    for (let i = 0; i < labelLayoutList.length; i++) {
223	        const layout = labelLayoutList[i];
224	        if (!isPositionCenter(layout) && layout.linePoints) {
225	            const label = layout.label;
226	            const linePoints = layout.linePoints;
227	            const isAlignToEdge = layout.labelAlignTo === 'edge';
228	            const padding = label.style.padding as number[];
229	            const paddingH = padding ? padding[1] + padding[3] : 0;
230	            // textRect.width already contains paddingH if bgColor is set
231	            const extraPaddingH = label.style.backgroundColor ? 0 : paddingH;
232	            const realTextWidth = layout.rect.width + extraPaddingH;
233	            const dist = linePoints[1][0] - linePoints[2][0];
234	            if (isAlignToEdge) {
235	                if (label.x < cx) {
236	                    linePoints[2][0] = viewLeft + layout.edgeDistance + realTextWidth + layout.labelDistance;
237	                }
238	                else {
239	                    linePoints[2][0] = viewLeft + viewWidth - layout.edgeDistance
240	                            - realTextWidth - layout.labelDistance;
241	                }
242	            }
243	            else {
244	                if (label.x < cx) {
245	                    linePoints[2][0] = label.x + layout.labelDistance;
246	                }
247	                else {
248	                    linePoints[2][0] = label.x - layout.labelDistance;
249	                }
250	                linePoints[1][0] = linePoints[2][0] + dist;
251	            }
252	            linePoints[1][1] = linePoints[2][1] = label.y;
253	        }
254	    }
255	}
