494	function getRichItemNames<
495	    TNuance extends TextCommonOptionNuanceBase
496	>(textStyleModel: Model<LabelCommonOption<TNuance>>) {
497	    // Use object to remove duplicated names.
498	    let richItemNameMap: Dictionary<number>;
499	    while (textStyleModel && textStyleModel !== textStyleModel.ecModel) {
500	        const rich = (textStyleModel.option || EMPTY_OBJ as LabelOption).rich;
501	        if (rich) {
502	            richItemNameMap = richItemNameMap || {};
503	            const richKeys = keys(rich);
504	            for (let i = 0; i < richKeys.length; i++) {
505	                const richKey = richKeys[i];
506	                richItemNameMap[richKey] = 1;
