320	): void {
321	    const axis = axisModel.axis;
322	    const record = shared.ensureRecord(axisModel);
323	    const labelInfoList: AxisBuilderSharedContextRecord['labelInfoList'] = [];
324	    let stOccupiedRect: AxisBuilderSharedContextRecord['stOccupiedRect'];
325	    const useStOccupiedRect = hasAxisName(cfg.axisName) && isNameLocationCenter(cfg.nameLocation);
326	
327	    each(labelLayoutInfoList, layout => {
328	        const layoutInfo = ensureLabelLayoutInfoComputed(layout);
329	        if (!layoutInfo || layoutInfo.label.ignore) {
330	            return;
331	        }
332	        labelInfoList.push(layoutInfo);
333	
334	        const transGroup = record.transGroup;
335	        if (useStOccupiedRect) {
336	            // Transform to "standard axis" for creating stOccupiedRect (the label rects union).
337	            transGroup.transform
