346	                ? stOccupiedRect.union(_stLabelRectTmp)
347	                : BoundingRect.copy(stOccupiedRect = new BoundingRect(0, 0, 0, 0), _stLabelRectTmp);
348	        }
349	    });
350	
351	    const sortByDim = Math.abs(record.dirVec.x) > 0.1 ? 'x' : 'y';
352	    const sortByValue = record.transGroup[sortByDim];
353	    labelInfoList.sort((info1, info2) => (
354	        Math.abs(info1.label[sortByDim] - sortByValue) - Math.abs(info2.label[sortByDim] - sortByValue)
355	    ));
