357	    if (useStOccupiedRect && stOccupiedRect) {
358	        const extent = axis.getExtent();
359	        const axisLineX = Math.min(extent[0], extent[1]);
360	        const axisLineWidth = Math.max(extent[0], extent[1]) - axisLineX;
