### 1c. `applyTextMarginToLocalRect` — current (lines 231-246)

```ts
/**
 * The input localRect is never modified.
 * The returned localRect maybe the input localRect.
 */
export function applyTextMarginToLocalRect(
    label: ZRText,
    localRect: BoundingRect,
): BoundingRect {
    if ((label.style as LabelExtendedTextStyle).__marginType !== LabelMarginType.textMargin) {
        return localRect;
    }
    const textMargin = normalizeCssArray(retrieve2(label.style.margin, [0, 0]));
    localRect = localRect.clone();
    expandOrShrinkRect(localRect, textMargin, false, false);
    return localRect;
}
```

Replace the whole block with:

```ts
/**
 * Retrieve the margin declared on a label, normalized to `[top, right, bottom, left]`
 * in the label local coordinate system. This is the single geometry rule for label margin:
 *  - `textMargin`: used as is (@see `format.ts#normalizeCssArray`).
 *  - `minMargin`: works like CSS margin collapse (gap between two labels is
 *    `label1.minMargin / 2 + label2.minMargin / 2`), thus half of it is applied on each side.
 * Return `NullUndefined` if no margin is declared.
 * [CAUTION] The returned array may be the internal `label.style.margin`; do not modify it.
 */
export function getLabelMarginDelta(label: ZRText): number[] | NullUndefined {
    const style = label.style as LabelExtendedTextStyle;
    const marginType = style.__marginType;
    if (marginType == null || style.margin == null) {
        return;
    }
    if (marginType === LabelMarginType.minMargin) {
        // `minMargin` only supports number value.
        const half = ((style.margin as number) || 0) / 2;
        return [half, half, half, half];
    }
    return normalizeCssArray(style.margin);
}

/**
 * Expand the label local rect by the declared label margin (`minMargin` or `textMargin`).
 * The input localRect is never modified.
 * The returned localRect maybe the input localRect.
 */
export function applyLabelMarginToLocalRect(
    label: ZRText,
    localRect: BoundingRect,
    ignoreMargin?: boolean
): BoundingRect {
    const margin = ignoreMargin ? null : getLabelMarginDelta(label);
    if (!margin) {
        return localRect;
    }
    localRect = localRect.clone();
    expandOrShrinkRect(localRect, margin, false, false);
    return localRect;
}
```

`applyTextMarginToLocalRect` has exactly one caller (`labelLayoutHelper.ts:135`) and is not re-exported from any public API entry (`rg` over `src/export`, `src/echarts.ts`, `src/extension.ts` finds nothing), so the rename is safe.

